def crear_base_y_tabla():
    conexion = None
    cursor = None

    try:
        conexion = mysql.connector.connect(
            host=DB_HOST,
            user=DB_USER,
            password=DB_PASSWORD,
            port=DB_PORT
        )

        cursor = conexion.cursor()

        cursor.execute(
            f"""
            CREATE DATABASE IF NOT EXISTS {DB_NAME}
            CHARACTER SET utf8mb4
            COLLATE utf8mb4_unicode_ci
            """
        )

        cursor.execute(f"USE {DB_NAME}")

        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS maestros (
                id INT AUTO_INCREMENT PRIMARY KEY,
                folio VARCHAR(20) UNIQUE,
                nombre VARCHAR(80) NOT NULL,
                apellidos VARCHAR(120) NOT NULL,
                edad INT NOT NULL,
                sexo VARCHAR(30) NOT NULL,
                nacionalidad VARCHAR(70) NOT NULL,
                curp VARCHAR(18) NOT NULL UNIQUE,
                carrera VARCHAR(180) NOT NULL,
                cedula_profesional VARCHAR(40),
                estudios_posgrado VARCHAR(220),
                cedula_posgrado VARCHAR(40),
                nivel_academico VARCHAR(50) NOT NULL DEFAULT 'Licenciatura',
                programa_academico VARCHAR(180) NOT NULL DEFAULT '',
                modalidad VARCHAR(50) NOT NULL DEFAULT 'Escolarizado',
                anios_experiencia INT NOT NULL DEFAULT 0,
                cargo VARCHAR(120) NOT NULL,
                tipo_personal VARCHAR(50) NOT NULL,
                numero_empleado VARCHAR(25) UNIQUE,
                telefono VARCHAR(30),
                correo VARCHAR(120),
                domicilio VARCHAR(255),
                fecha_ingreso DATE,
                estado_personal VARCHAR(30) NOT NULL DEFAULT 'Activo',
                tipo_contrato VARCHAR(60),
                fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                fecha_actualizacion TIMESTAMP
                    DEFAULT CURRENT_TIMESTAMP
                    ON UPDATE CURRENT_TIMESTAMP
            )
            """
        )

        cursor.execute("SHOW COLUMNS FROM maestros")
        columnas_existentes = {fila[0] for fila in cursor.fetchall()}

        migraciones = {
            "folio": "ALTER TABLE maestros ADD COLUMN folio VARCHAR(20) UNIQUE AFTER id",
            "nivel_academico": "ALTER TABLE maestros ADD COLUMN nivel_academico VARCHAR(50) NOT NULL DEFAULT 'Licenciatura' AFTER cedula_posgrado",
            "programa_academico": "ALTER TABLE maestros ADD COLUMN programa_academico VARCHAR(180) NOT NULL DEFAULT '' AFTER nivel_academico",
            "modalidad": "ALTER TABLE maestros ADD COLUMN modalidad VARCHAR(50) NOT NULL DEFAULT 'Escolarizado' AFTER programa_academico",
            "foto": "ALTER TABLE maestros ADD COLUMN foto LONGBLOB NULL AFTER modalidad",
            "numero_empleado": "ALTER TABLE maestros ADD COLUMN numero_empleado VARCHAR(25) UNIQUE AFTER tipo_personal",
            "telefono": "ALTER TABLE maestros ADD COLUMN telefono VARCHAR(30) NULL AFTER numero_empleado",
            "correo": "ALTER TABLE maestros ADD COLUMN correo VARCHAR(120) NULL AFTER telefono",
            "domicilio": "ALTER TABLE maestros ADD COLUMN domicilio VARCHAR(255) NULL AFTER correo",
            "fecha_ingreso": "ALTER TABLE maestros ADD COLUMN fecha_ingreso DATE NULL AFTER domicilio",
            "estado_personal": "ALTER TABLE maestros ADD COLUMN estado_personal VARCHAR(30) NOT NULL DEFAULT 'Activo' AFTER fecha_ingreso",
            "tipo_contrato": "ALTER TABLE maestros ADD COLUMN tipo_contrato VARCHAR(60) NULL AFTER estado_personal"
        }

        for columna, sentencia in migraciones.items():
            if columna not in columnas_existentes:
                cursor.execute(sentencia)

        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS historial_movimientos (
                id INT AUTO_INCREMENT PRIMARY KEY,
                maestro_id INT NULL,
                folio VARCHAR(20),
                accion VARCHAR(30) NOT NULL,
                detalle VARCHAR(255),
                fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """
        )

        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS nominas (
                id INT AUTO_INCREMENT PRIMARY KEY,
                maestro_id INT NOT NULL UNIQUE,
                pago_hora DECIMAL(12,2) NOT NULL DEFAULT 0,
                horas_semana DECIMAL(8,2) NOT NULL DEFAULT 0,
                horas_trabajadas DECIMAL(8,2) NOT NULL DEFAULT 0,
                horas_faltadas DECIMAL(8,2) NOT NULL DEFAULT 0,
                bonos DECIMAL(12,2) NOT NULL DEFAULT 0,
                descuentos DECIMAL(12,2) NOT NULL DEFAULT 0,
                pago_semanal DECIMAL(12,2) NOT NULL DEFAULT 0,
                pago_quincenal DECIMAL(12,2) NOT NULL DEFAULT 0,
                pago_mensual DECIMAL(12,2) NOT NULL DEFAULT 0,
                pago_neto DECIMAL(12,2) NOT NULL DEFAULT 0,
                periodo_inicio DATE,
                periodo_fin DATE,
                estado VARCHAR(20) NOT NULL DEFAULT 'Pendiente',
                descuento_faltas DECIMAL(12,2) NOT NULL DEFAULT 0,
                fecha_pago DATE,
                fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    ON UPDATE CURRENT_TIMESTAMP,
                CONSTRAINT fk_nomina_maestro
                    FOREIGN KEY (maestro_id) REFERENCES maestros(id)
                    ON DELETE CASCADE
            )
            """
        )

        cursor.execute("SHOW COLUMNS FROM nominas")
        columnas_nomina = {fila[0] for fila in cursor.fetchall()}
        migraciones_nomina = {
            "horas_trabajadas": "ALTER TABLE nominas ADD COLUMN horas_trabajadas DECIMAL(8,2) NOT NULL DEFAULT 0 AFTER horas_semana",
            "horas_faltadas": "ALTER TABLE nominas ADD COLUMN horas_faltadas DECIMAL(8,2) NOT NULL DEFAULT 0 AFTER horas_trabajadas",
            "periodo_inicio": "ALTER TABLE nominas ADD COLUMN periodo_inicio DATE NULL AFTER pago_neto",
            "periodo_fin": "ALTER TABLE nominas ADD COLUMN periodo_fin DATE NULL AFTER periodo_inicio",
            "estado": "ALTER TABLE nominas ADD COLUMN estado VARCHAR(20) NOT NULL DEFAULT 'Pendiente' AFTER periodo_fin",
            "descuento_faltas": "ALTER TABLE nominas ADD COLUMN descuento_faltas DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER estado",
            "fecha_pago": "ALTER TABLE nominas ADD COLUMN fecha_pago DATE NULL AFTER descuento_faltas"
        }
        for columna, sentencia in migraciones_nomina.items():
            if columna not in columnas_nomina:
                cursor.execute(sentencia)

        cursor.execute(
            """
            UPDATE maestros
            SET folio = CONCAT('CESGRO-', LPAD(id, 4, '0'))
            WHERE folio IS NULL OR TRIM(folio) = ''
            """
        )
        cursor.execute(
            """
            UPDATE maestros
            SET numero_empleado = CONCAT('EMP-', LPAD(id, 4, '0'))
            WHERE numero_empleado IS NULL OR TRIM(numero_empleado) = ''
            """
        )

        # Permite conservar varios periodos de nómina por maestro.
        cursor.execute("SHOW INDEX FROM nominas")
        indices_nomina = cursor.fetchall()
        tiene_indice_normal = any(i[4] == 'maestro_id' and i[1] == 1 for i in indices_nomina)
        if not tiene_indice_normal:
            try:
                cursor.execute("ALTER TABLE nominas ADD INDEX idx_nominas_maestro (maestro_id)")
            except Error:
                pass
        for indice in indices_nomina:
            nombre_indice = indice[2]
            columna = indice[4]
            no_unico = indice[1]
            if columna == 'maestro_id' and no_unico == 0 and nombre_indice != 'PRIMARY':
                try:
                    cursor.execute(f"ALTER TABLE nominas DROP INDEX `{nombre_indice}`")
                except Error:
                    pass
                break

        conexion.commit()

    finally:
        if cursor:
            cursor.close()

        if conexion and conexion.is_connected():
            conexion.close()


def conectar():
    return mysql.connector.connect(
        host=DB_HOST,
        user=DB_USER,
        password=DB_PASSWORD,
        database=DB_NAME,
        port=DB_PORT
    )


