class BotonMenu(tk.Button):
    def __init__(self, padre, texto, comando):
        super().__init__(
            padre,
            text=texto,
            command=comando,
            anchor="w",
            padx=22,
            pady=13,
            bg=COLORES["azul_oscuro"],
            fg="#EAF5FB",
            activebackground="#0D5A84",
            activeforeground=COLORES["blanco"],
            font=("Segoe UI Semibold", 10),
            relief="flat",
            bd=0,
            cursor="hand2"
        )

        self.bind("<Enter>", lambda e: self.config(bg="#0D5A84"))
        self.bind("<Leave>", lambda e: self.config(bg=COLORES["azul_oscuro"]))


