    # --------------------------------------------------------
    # LOGO
    # --------------------------------------------------------

    def cargar_logo(self, tipo="azul"):
        datos_base64 = (
            LOGO_BLANCO_BASE64
            if tipo == "blanco"
            else LOGO_AZUL_BASE64
        )
        datos = base64.b64decode(datos_base64)
        return Image.open(BytesIO(datos)).convert("RGBA")

    def imagen_logo(self, ancho, alto=None, transparencia=255, tipo="azul"):
        alto = alto or ancho
        imagen = self.cargar_logo(tipo).copy()
        imagen.thumbnail((ancho, alto), Image.Resampling.LANCZOS)

        if transparencia < 255:
            canal = imagen.getchannel("A")
            canal = canal.point(lambda p: int(p * transparencia / 255))
            imagen.putalpha(canal)

        return ImageTk.PhotoImage(imagen)

    def imagen_logo_completo(self, ancho, alto=None):
        alto = alto or ancho
        datos = base64.b64decode(FULL_LOGO_BASE64)
        imagen = Image.open(BytesIO(datos)).convert("RGBA")
        imagen.thumbnail((ancho, alto), Image.Resampling.LANCZOS)
        return ImageTk.PhotoImage(imagen)


    def imagen_desde_bytes(self, datos, ancho, alto):
        if not datos:
            return None
        imagen = Image.open(BytesIO(datos)).convert("RGB")
        imagen.thumbnail((ancho, alto), Image.Resampling.LANCZOS)
        lienzo = Image.new("RGB", (ancho, alto), "#F4F8FB")
        x = (ancho - imagen.width) // 2
        y = (alto - imagen.height) // 2
        lienzo.paste(imagen, (x, y))
        return ImageTk.PhotoImage(lienzo)

    def seleccionar_foto(self):
        ruta = filedialog.askopenfilename(
            title="Seleccionar fotografía del docente",
            filetypes=[("Imágenes", "*.png;*.jpg;*.jpeg;*.webp")]
        )
        if not ruta:
            return
        try:
            with open(ruta, "rb") as archivo:
                self.foto_bytes = archivo.read()
            self.actualizar_preview_foto()
            self.actualizar_estado("Fotografía cargada correctamente", COLORES["verde"])
        except Exception as error:
            messagebox.showerror("Error", f"No se pudo cargar la fotografía.\n\n{error}")

    def limpiar_foto(self):
        self.foto_bytes = None
        self.actualizar_preview_foto()

    def actualizar_preview_foto(self, datos=None):
        if not hasattr(self, "marco_preview_foto") or self.marco_preview_foto is None:
            return
        datos = self.foto_bytes if datos is None else datos
        for widget in self.marco_preview_foto.winfo_children():
            widget.destroy()

        if datos:
            self.foto_preview = self.imagen_desde_bytes(datos, 220, 220)
            etiqueta = tk.Label(
                self.marco_preview_foto,
                image=self.foto_preview,
                bg="#F7FAFD",
                bd=0
            )
            etiqueta.pack(expand=True)
        else:
            iniciales = (
                (self.variables_formulario.get("nombre").get()[:1] if self.variables_formulario else "") +
                (self.variables_formulario.get("apellidos").get()[:1] if self.variables_formulario else "")
            ).upper() or "CE"
            tk.Label(
                self.marco_preview_foto,
                text=iniciales,
                bg="#E8F3FB",
                fg=COLORES["azul"],
                font=("Segoe UI Semibold", 38),
                width=7,
                height=3
            ).pack(expand=True, pady=(18, 10))
            tk.Label(
                self.marco_preview_foto,
                text="Sin fotografía",
                bg="#F7FAFD",
                fg=COLORES["texto_suave"],
                font=("Segoe UI", 10)
            ).pack(pady=(0, 16))

