    def actualizar_inicio(self):
        conexion = None
        cursor = None

        try:
            conexion = conectar()
            cursor = conexion.cursor(dictionary=True)

            cursor.execute(
                """
                SELECT
                    COUNT(*) AS total,
                    SUM(tipo_personal = 'Cuerpo docente') AS docentes,
                    SUM(tipo_personal = 'Cuerpo administrativo') AS administrativos,
                    SUM(tipo_personal = 'Cuerpo directivo') AS directivos,
                    SUM(
                        estudios_posgrado IS NOT NULL
                        AND TRIM(estudios_posgrado) <> ''
                    ) AS posgrado
                FROM maestros
                """
            )

            datos = cursor.fetchone()

            for clave, etiqueta in self.etiquetas_contadores.items():
                etiqueta.config(text=str(datos.get(clave) or 0))

            for elemento in self.tabla_recientes.get_children():
                self.tabla_recientes.delete(elemento)

            cursor.execute(
                """
                SELECT
                    folio,
                    CONCAT(nombre, ' ', apellidos) AS nombre_completo,
                    programa_academico,
                    modalidad,
                    DATE_FORMAT(fecha_registro, '%d/%m/%Y') AS fecha
                FROM maestros
                ORDER BY fecha_registro DESC
                LIMIT 8
                """
            )

            for registro in cursor.fetchall():
                self.tabla_recientes.insert(
                    "",
                    "end",
                    values=(
                        registro["folio"],
                        registro["nombre_completo"],
                        registro["programa_academico"],
                        registro["modalidad"],
                        registro["fecha"]
                    )
                )

        except Error as error:
            self.actualizar_estado(f"Error: {error}", COLORES["rojo"])

        finally:
            if cursor:
                cursor.close()

            if conexion and conexion.is_connected():
                conexion.close()

