    def actualizar_programas_academicos(self):
        if not self.variables_formulario:
            return

        nivel = self.variables_formulario["nivel_academico"].get() or "Licenciatura"
        programas = PROGRAMAS_ACADEMICOS.get(nivel, [])

        if self.combo_programa_academico:
            self.combo_programa_academico["values"] = programas

        actual = self.variables_formulario["programa_academico"].get()
        if actual not in programas:
            self.variables_formulario["programa_academico"].set(
                programas[0] if programas else ""
            )

    def convertir_curp(self, evento=None):
        texto = self.variables_formulario["curp"].get().upper()[:18]
        self.variables_formulario["curp"].set(texto)

    def validar_curp(self, curp):
        patron = r"^[A-Z]{4}\d{6}[HM][A-Z]{5}[A-Z0-9]\d$"
        return re.fullmatch(patron, curp) is not None

    def validar_formulario(self):
        obligatorios = {
            "nombre": "Nombre",
            "apellidos": "Apellido(s)",
            "edad": "Edad",
            "sexo": "Sexo",
            "nacionalidad": "Nacionalidad",
            "curp": "CURP",
            "carrera": "Nombre de la carrera",
            "nivel_academico": "Nivel académico",
            "programa_academico": "Programa académico",
            "modalidad": "Modalidad",
            "anios_experiencia": "Años de experiencia",
            "cargo": "Cargo",
            "tipo_personal": "Tipo de personal"
        }

        for clave, texto in obligatorios.items():
            if not self.variables_formulario[clave].get().strip():
                messagebox.showwarning(
                    "Campo obligatorio",
                    f"Completa el campo: {texto}."
                )
                return False

        try:
            edad = int(self.variables_formulario["edad"].get())
            if not 18 <= edad <= 100:
                raise ValueError
        except ValueError:
            messagebox.showwarning(
                "Edad inválida",
                "La edad debe ser un número entre 18 y 100."
            )
            return False

        try:
            experiencia = int(
                self.variables_formulario["anios_experiencia"].get()
            )
            if not 0 <= experiencia <= 80:
                raise ValueError
        except ValueError:
            messagebox.showwarning(
                "Experiencia inválida",
                "Los años de experiencia deben estar entre 0 y 80."
            )
            return False

        curp = self.variables_formulario["curp"].get().strip().upper()

        if not self.validar_curp(curp):
            messagebox.showwarning(
                "CURP inválida",
                "La CURP debe contener 18 caracteres y tener un formato válido."
            )
            return False

        correo = self.variables_formulario.get("correo", tk.StringVar()).get().strip()
        if correo and not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", correo):
            messagebox.showwarning("Correo inválido", "Escribe un correo electrónico válido.")
            return False
        fecha_ingreso = self.variables_formulario.get("fecha_ingreso", tk.StringVar()).get().strip()
        if fecha_ingreso:
            try:
                datetime.strptime(fecha_ingreso, "%Y-%m-%d")
            except ValueError:
                messagebox.showwarning("Fecha inválida", "La fecha de ingreso debe escribirse como AAAA-MM-DD.")
                return False

        return True

    def obtener_datos(self):
        return (
            self.variables_formulario["nombre"].get().strip().title(),
            self.variables_formulario["apellidos"].get().strip().title(),
            int(self.variables_formulario["edad"].get()),
            self.variables_formulario["sexo"].get().strip(),
            self.variables_formulario["nacionalidad"].get().strip().title(),
            self.variables_formulario["curp"].get().strip().upper(),
            self.variables_formulario["carrera"].get().strip(),
            self.variables_formulario["cedula_profesional"].get().strip(),
            self.variables_formulario["estudios_posgrado"].get().strip(),
            self.variables_formulario["cedula_posgrado"].get().strip(),
            self.variables_formulario["nivel_academico"].get().strip(),
            self.variables_formulario["programa_academico"].get().strip(),
            self.variables_formulario["modalidad"].get().strip(),
            self.foto_bytes,
            int(self.variables_formulario["anios_experiencia"].get()),
            self.variables_formulario["cargo"].get().strip().title(),
            self.variables_formulario["tipo_personal"].get().strip(),
            self.variables_formulario["telefono"].get().strip(),
            self.variables_formulario["correo"].get().strip().lower(),
            self.variables_formulario["domicilio"].get().strip(),
            self.variables_formulario["fecha_ingreso"].get().strip() or None,
            self.variables_formulario["estado_personal"].get().strip(),
            self.variables_formulario["tipo_contrato"].get().strip()
        )

    def guardar_registro(self):
        if not self.validar_formulario():
            return

        conexion = None
        cursor = None

        try:
            conexion = conectar()
            cursor = conexion.cursor()

            cursor.execute(
                """
                INSERT INTO maestros (
                    nombre,
                    apellidos,
                    edad,
                    sexo,
                    nacionalidad,
                    curp,
                    carrera,
                    cedula_profesional,
                    estudios_posgrado,
                    cedula_posgrado,
                    nivel_academico,
                    programa_academico,
                    modalidad,
                    foto,
                    anios_experiencia,
                    cargo,
                    tipo_personal,
                    telefono,
                    correo,
                    domicilio,
                    fecha_ingreso,
                    estado_personal,
                    tipo_contrato
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """,
                self.obtener_datos()
            )

            maestro_id = cursor.lastrowid
            folio = f"CESGRO-{maestro_id:04d}"
            numero_empleado = f"EMP-{maestro_id:04d}"
            cursor.execute(
                "UPDATE maestros SET folio=%s, numero_empleado=%s WHERE id=%s",
                (folio, numero_empleado, maestro_id)
            )
            cursor.execute(
                """
                INSERT INTO historial_movimientos
                    (maestro_id, folio, accion, detalle)
                VALUES (%s, %s, 'REGISTRO', %s)
                """,
                (maestro_id, folio, "Alta de maestro")
            )
            conexion.commit()

            messagebox.showinfo(
                "Registro guardado",
                f"El maestro fue registrado correctamente.\n\nFolio: {folio}"
            )

            self.actualizar_estado(
                "Registro guardado correctamente",
                COLORES["verde"]
            )

            self.limpiar_formulario()

        except Error as error:
            if error.errno == 1062:
                messagebox.showwarning(
                    "CURP duplicada",
                    "Ya existe una persona registrada con esa CURP."
                )
            else:
                messagebox.showerror(
                    "Error",
                    f"No se pudo guardar el registro.\n\n{error}"
                )

        finally:
            if cursor:
                cursor.close()

            if conexion and conexion.is_connected():
                conexion.close()

    def actualizar_registro(self):
        if not self.id_seleccionado:
            messagebox.showwarning(
                "Sin selección",
                "Selecciona un registro desde Consultar personal."
            )
            return

        if not self.validar_formulario():
            return

        conexion = None
        cursor = None

        try:
            conexion = conectar()
            cursor = conexion.cursor()

            cursor.execute(
                """
                UPDATE maestros
                SET
                    nombre=%s,
                    apellidos=%s,
                    edad=%s,
                    sexo=%s,
                    nacionalidad=%s,
                    curp=%s,
                    carrera=%s,
                    cedula_profesional=%s,
                    estudios_posgrado=%s,
                    cedula_posgrado=%s,
                    nivel_academico=%s,
                    programa_academico=%s,
                    modalidad=%s,
                    foto=%s,
                    anios_experiencia=%s,
                    cargo=%s,
                    tipo_personal=%s,
                    telefono=%s,
                    correo=%s,
                    domicilio=%s,
                    fecha_ingreso=%s,
                    estado_personal=%s,
                    tipo_contrato=%s
                WHERE id=%s
                """,
                self.obtener_datos() + (self.id_seleccionado,)
            )

            cursor.execute(
                "SELECT folio FROM maestros WHERE id=%s",
                (self.id_seleccionado,)
            )
            fila_folio = cursor.fetchone()
            folio = fila_folio[0] if fila_folio else None
            cursor.execute(
                """
                INSERT INTO historial_movimientos
                    (maestro_id, folio, accion, detalle)
                VALUES (%s, %s, 'ACTUALIZACIÓN', %s)
                """,
                (self.id_seleccionado, folio, "Actualización de datos")
            )
            conexion.commit()

            messagebox.showinfo(
                "Registro actualizado",
                "La información fue actualizada correctamente."
            )

            self.limpiar_formulario()

        except Error as error:
            messagebox.showerror(
                "Error",
                f"No se pudo actualizar el registro.\n\n{error}"
            )

        finally:
            if cursor:
                cursor.close()

            if conexion and conexion.is_connected():
                conexion.close()

    def eliminar_registro(self):
        if not self.id_seleccionado:
            messagebox.showwarning(
                "Sin selección",
                "Selecciona un registro desde Consultar personal."
            )
            return

        if not messagebox.askyesno(
            "Confirmar eliminación",
            "¿Seguro que deseas eliminar este registro?"
        ):
            return

        self.eliminar_por_id(self.id_seleccionado)
        self.limpiar_formulario()

    def limpiar_formulario(self):
        if not self.variables_formulario:
            return

        valores = {
            "nacionalidad": "Mexicana",
            "nivel_academico": "Licenciatura",
            "modalidad": "Escolarizado",
            "anios_experiencia": "0",
            "tipo_personal": "Cuerpo docente",
            "fecha_ingreso": datetime.now().strftime("%Y-%m-%d"),
            "estado_personal": "Activo",
            "tipo_contrato": "Por horas"
        }

        for clave, variable in self.variables_formulario.items():
            variable.set(valores.get(clave, ""))

        self.actualizar_programas_academicos()
        self.id_seleccionado = None
        self.foto_bytes = None
        self.actualizar_preview_foto()

