    def buscar_en_vivo(self, evento=None):
        if self.temporizador_busqueda:
            self.after_cancel(self.temporizador_busqueda)

        self.temporizador_busqueda = self.after(300, self.buscar_personal)

    def mostrar_todos(self):
        self.variable_busqueda.set("")
        self.variable_filtro.set("Todos")
        self.buscar_personal()

    def buscar_personal(self):
        texto = self.variable_busqueda.get().strip()
        filtro = self.variable_filtro.get()

        conexion = None
        cursor = None

        try:
            conexion = conectar()
            cursor = conexion.cursor(dictionary=True)

            consulta = """
                SELECT
                    id,
                    CONCAT(nombre, ' ', apellidos) AS nombre_completo,
                    curp,
                    carrera,
                    anios_experiencia,
                    cargo,
                    tipo_personal
                FROM maestros
                WHERE (
                    curp LIKE %s
                    OR nombre LIKE %s
                    OR apellidos LIKE %s
                    OR carrera LIKE %s
                    OR programa_academico LIKE %s
                    OR modalidad LIKE %s
                    OR cargo LIKE %s
                )
            """

            patron = f"%{texto}%"
            parametros = [patron, patron, patron, patron, patron, patron, patron]

            if filtro != "Todos":
                consulta += " AND tipo_personal = %s"
                parametros.append(filtro)

            consulta += " ORDER BY apellidos, nombre"

            cursor.execute(consulta, tuple(parametros))
            registros = cursor.fetchall()

            for elemento in self.tabla_consulta.get_children():
                self.tabla_consulta.delete(elemento)

            for indice, registro in enumerate(registros):
                etiqueta = "par" if indice % 2 == 0 else "impar"

                self.tabla_consulta.insert(
                    "",
                    "end",
                    values=(
                        registro["id"],
                        registro["nombre_completo"],
                        registro["curp"],
                        registro["carrera"],
                        f'{registro["anios_experiencia"]} años',
                        registro["cargo"],
                        registro["tipo_personal"]
                    ),
                    tags=(etiqueta,)
                )

            self.tabla_consulta.tag_configure(
                "par",
                background=COLORES["blanco"]
            )
            self.tabla_consulta.tag_configure(
                "impar",
                background=COLORES["fila"]
            )

            self.actualizar_estado(
                f"{len(registros)} registro(s) encontrado(s)"
            )

        except Error as error:
            messagebox.showerror(
                "Error",
                f"No se pudo realizar la búsqueda.\n\n{error}"
            )

        finally:
            if cursor:
                cursor.close()

            if conexion and conexion.is_connected():
                conexion.close()

    def obtener_registro(self, registro_id):
        conexion = None
        cursor = None

        try:
            conexion = conectar()
            cursor = conexion.cursor(dictionary=True)

            cursor.execute(
                "SELECT * FROM maestros WHERE id = %s",
                (registro_id,)
            )

            return cursor.fetchone()

        finally:
            if cursor:
                cursor.close()

            if conexion and conexion.is_connected():
                conexion.close()

