    def numero_nomina(self, variable):
        valor = variable.get().strip().replace(",", "")
        if not valor:
            return 0.0
        try:
            return max(0.0, float(valor))
        except ValueError:
            return 0.0

    def calcular_nomina(self):
        pago_hora=self.numero_nomina(self.var_pago_hora)
        programadas=self.numero_nomina(self.var_horas_semana)
        trabajadas=min(max(self.numero_nomina(self.var_horas_trabajadas),0),programadas if programadas>0 else 0)
        faltadas=max(programadas-trabajadas,0)
        bonos=self.numero_nomina(self.var_bonos)
        otros_descuentos=self.numero_nomina(self.var_descuentos)
        pago_programado=pago_hora*programadas
        descuento_faltas=pago_hora*faltadas
        pago_real=pago_hora*trabajadas
        total=max(pago_real+bonos-otros_descuentos,0)
        self.var_horas_faltadas.set(f"{faltadas:.2f}")
        self.var_pago_programado.set(self.formato_moneda(pago_programado))
        self.var_descuento_faltas.set(f"-{self.formato_moneda(descuento_faltas)}")
        self.var_pago_real.set(self.formato_moneda(pago_real))
        self.var_pago_neto.set(self.formato_moneda(total))
        self.nomina_calculos={"pago_hora":pago_hora,"horas":programadas,"horas_trabajadas":trabajadas,"horas_faltadas":faltadas,"bonos":bonos,"descuentos":otros_descuentos,"descuento_faltas":descuento_faltas,"pago_programado":pago_programado,"pago_semanal":pago_real,"pago_quincenal":pago_real,"pago_mensual":pago_real,"pago_neto":total}

    def cargar_lista_maestros_nomina(self):
        conexion = None
        cursor = None
        try:
            conexion = conectar()
            cursor = conexion.cursor(dictionary=True)
            cursor.execute(
                """
                SELECT id, folio, CONCAT(nombre, ' ', apellidos) AS nombre
                FROM maestros
                WHERE tipo_personal = 'Cuerpo docente'
                ORDER BY apellidos, nombre
                """
            )
            valores = []
            self.nomina_mapa_maestros = {}
            for fila in cursor.fetchall():
                texto = f"{fila['folio'] or 'Sin folio'} · {fila['nombre']}"
                valores.append(texto)
                self.nomina_mapa_maestros[texto] = fila["id"]
            self.combo_nomina_maestro["values"] = valores
        except Error as error:
            messagebox.showerror("Error", f"No se pudieron cargar los maestros.\n\n{error}")
        finally:
            if cursor:
                cursor.close()
            if conexion and conexion.is_connected():
                conexion.close()

    def cargar_nomina_maestro(self, evento=None):
        texto=self.var_nomina_maestro.get()
        self.nomina_maestro_id=self.nomina_mapa_maestros.get(texto)
        if not self.nomina_maestro_id:
            return
        if self.nomina_id_seleccionada is None:
            self.var_pago_hora.set("0")
            self.var_horas_semana.set("0")
            self.var_horas_trabajadas.set("0")
            self.var_bonos.set("0")
            self.var_descuentos.set("0")
            self.calcular_nomina()

    def validar_periodo_nomina(self):
        try:
            inicio=datetime.strptime(self.var_periodo_inicio.get().strip(),"%Y-%m-%d").date()
            fin=datetime.strptime(self.var_periodo_fin.get().strip(),"%Y-%m-%d").date()
        except ValueError:
            messagebox.showwarning("Periodo inválido","Escribe las fechas como AAAA-MM-DD.")
            return None
        if fin<inicio:
            messagebox.showwarning("Periodo inválido","La fecha final no puede ser anterior a la inicial.")
            return None
        return inicio,fin

    def guardar_nomina(self):
        if not self.nomina_maestro_id:
            messagebox.showwarning("Selecciona un maestro", "Selecciona al maestro antes de guardar el pago.")
            return
        self.calcular_nomina()
        d = self.nomina_calculos
        if d["pago_hora"] <= 0 or d["horas"] <= 0:
            messagebox.showwarning("Datos inválidos", "El pago por hora y las horas programadas deben ser mayores que cero.")
            return
        conexion = cursor = None
        try:
            hoy = datetime.now().date()
            conexion = conectar()
            cursor = conexion.cursor()
            cursor.execute(
                """
                INSERT INTO nominas (
                    maestro_id, pago_hora, horas_semana, horas_trabajadas,
                    horas_faltadas, bonos, descuentos, pago_semanal,
                    pago_quincenal, pago_mensual, pago_neto, periodo_inicio,
                    periodo_fin, estado, descuento_faltas, fecha_pago
                ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """,
                (
                    self.nomina_maestro_id, d["pago_hora"], d["horas"], d["horas_trabajadas"],
                    d["horas_faltadas"], d["bonos"], d["descuentos"], d["pago_semanal"],
                    d["pago_quincenal"], d["pago_mensual"], d["pago_neto"], hoy, hoy,
                    "Pagado", d["descuento_faltas"], hoy
                )
            )
            conexion.commit()
            self.nomina_id_seleccionada = cursor.lastrowid
            messagebox.showinfo("Pago guardado", "El pago fue registrado correctamente.")
            self.actualizar_tabla_nomina()
        except Error as error:
            messagebox.showerror("Error", f"No se pudo guardar el pago.\n\n{error}")
        finally:
            if cursor:
                cursor.close()
            if conexion and conexion.is_connected():
                conexion.close()

    def actualizar_nomina_seleccionada(self):
        if not self.nomina_id_seleccionada:
            messagebox.showwarning("Sin selección", "Selecciona un pago guardado de la tabla para actualizarlo.")
            return
        self.calcular_nomina()
        d = self.nomina_calculos
        conexion = cursor = None
        try:
            hoy = datetime.now().date()
            conexion = conectar()
            cursor = conexion.cursor()
            cursor.execute(
                """
                UPDATE nominas
                SET maestro_id=%s, pago_hora=%s, horas_semana=%s, horas_trabajadas=%s,
                    horas_faltadas=%s, bonos=%s, descuentos=%s, pago_semanal=%s,
                    pago_quincenal=%s, pago_mensual=%s, pago_neto=%s,
                    periodo_inicio=%s, periodo_fin=%s, estado=%s,
                    descuento_faltas=%s, fecha_pago=%s
                WHERE id=%s
                """,
                (
                    self.nomina_maestro_id, d["pago_hora"], d["horas"], d["horas_trabajadas"],
                    d["horas_faltadas"], d["bonos"], d["descuentos"], d["pago_semanal"],
                    d["pago_quincenal"], d["pago_mensual"], d["pago_neto"],
                    hoy, hoy, "Pagado", d["descuento_faltas"], hoy, self.nomina_id_seleccionada
                )
            )
            conexion.commit()
            messagebox.showinfo("Pago actualizado", "Los datos del pago se actualizaron correctamente.")
            self.actualizar_tabla_nomina()
        except Error as error:
            messagebox.showerror("Error", f"No se pudo actualizar el pago.\n\n{error}")
        finally:
            if cursor:
                cursor.close()
            if conexion and conexion.is_connected():
                conexion.close()

    def actualizar_tabla_nomina(self):
        tabla = getattr(self, "tabla_historial_pagos", None)
        if tabla is None or not tabla.winfo_exists():
            return
        for item in tabla.get_children():
            tabla.delete(item)
        conexion = cursor = None
        try:
            conexion = conectar()
            cursor = conexion.cursor(dictionary=True)
            cursor.execute("""
                SELECT n.id, CONCAT(m.nombre, ' ', m.apellidos) AS maestro,
                       n.pago_hora, n.horas_semana, n.horas_trabajadas,
                       n.horas_faltadas, n.descuento_faltas, n.bonos,
                       n.descuentos, n.pago_neto, n.fecha_pago
                FROM nominas n
                JOIN maestros m ON m.id=n.maestro_id
                ORDER BY n.id DESC
            """)
            filas = cursor.fetchall()
            for i, f in enumerate(filas):
                tabla.insert("", "end", values=(
                    f["id"], f["maestro"], self.formato_moneda(f["pago_hora"]),
                    f'{float(f["horas_semana"] or 0):.2f}', f'{float(f["horas_trabajadas"] or 0):.2f}',
                    f'{float(f["horas_faltadas"] or 0):.2f}', self.formato_moneda(f["descuento_faltas"]),
                    self.formato_moneda(f["bonos"]), self.formato_moneda(f["descuentos"]),
                    self.formato_moneda(f["pago_neto"]),
                    f["fecha_pago"].strftime("%d/%m/%Y") if f["fecha_pago"] else "-"
                ), tags=("par" if i % 2 == 0 else "impar",))
            tabla.tag_configure("par", background=COLORES["blanco"])
            tabla.tag_configure("impar", background=COLORES["fila"])
            if hasattr(self, "etiqueta_cantidad_historial"):
                self.etiqueta_cantidad_historial.config(text=f"{len(filas)} pago(s)")
        except Error as error:
            messagebox.showerror("Error", f"No se pudo cargar el historial.\n\n{error}")
        finally:
            if cursor:
                cursor.close()
            if conexion and conexion.is_connected():
                conexion.close()

    def seleccionar_nomina_tabla(self, evento=None):
        seleccion = self.tabla_nomina.selection()
        if not seleccion:
            return
        valores = self.tabla_nomina.item(seleccion[0], "values")
        if not valores or not valores[0]:
            return
        self.nomina_id_seleccionada = int(valores[0])
        conexion = cursor = None
        try:
            conexion = conectar()
            cursor = conexion.cursor(dictionary=True)
            cursor.execute("SELECT * FROM nominas WHERE id=%s", (self.nomina_id_seleccionada,))
            n = cursor.fetchone()
            if not n:
                return
            self.nomina_maestro_id = n["maestro_id"]
            for texto, mid in self.nomina_mapa_maestros.items():
                if mid == self.nomina_maestro_id:
                    self.var_nomina_maestro.set(texto)
                    break
            self.var_pago_hora.set(f'{float(n["pago_hora"] or 0):.2f}')
            self.var_horas_semana.set(f'{float(n["horas_semana"] or 0):.2f}')
            self.var_horas_trabajadas.set(f'{float(n["horas_trabajadas"] or 0):.2f}')
            self.var_bonos.set(f'{float(n["bonos"] or 0):.2f}')
            self.var_descuentos.set(f'{float(n["descuentos"] or 0):.2f}')
            self.calcular_nomina()
        finally:
            if cursor:
                cursor.close()
            if conexion and conexion.is_connected():
                conexion.close()

    def limpiar_nomina(self):
        self.nomina_id_seleccionada = None
        self.nomina_maestro_id = None
        self.var_nomina_maestro.set("")
        for v in (self.var_pago_hora, self.var_horas_semana, self.var_horas_trabajadas, self.var_bonos, self.var_descuentos):
            v.set("0")
        self.calcular_nomina()
        if hasattr(self, "tabla_nomina"):
            self.tabla_nomina.selection_remove(self.tabla_nomina.selection())

    def mostrar_historial_pagos(self):
        self.limpiar_contenido()
        self.colocar_logo_fondo()
