            estilo_texto = ParagraphStyle("txt", parent=estilos["Normal"], fontName="Helvetica", fontSize=8.5, leading=11, textColor=gris)
            estilo_pie = ParagraphStyle("pie", parent=estilos["Normal"], fontName="Helvetica", fontSize=7.5, leading=10, textColor=gris, alignment=TA_CENTER)

