    def eliminar_nomina(self):
        if not self.nomina_id_seleccionada:
            messagebox.showwarning("Sin selección", "Selecciona un pago guardado.")
            return
        if not messagebox.askyesno("Confirmar eliminación", "¿Seguro que deseas eliminar este pago?"):
            return
        conexion=cursor=None
        try:
            conexion=conectar(); cursor=conexion.cursor(); cursor.execute("DELETE FROM nominas WHERE id=%s",(self.nomina_id_seleccionada,)); conexion.commit(); messagebox.showinfo("Pago eliminado", "El pago fue eliminado correctamente.")
            if hasattr(self, "var_nomina_maestro"):
                self.limpiar_nomina()
            self.actualizar_tabla_nomina()
        except Error as error: messagebox.showerror("Error", f"No se pudo eliminar la nómina.\n\n{error}")
        finally:
            if cursor:cursor.close()
            if conexion and conexion.is_connected():conexion.close()

