    def actualizar_reporte(self):
        conexion = None
        cursor = None

        try:
            conexion = conectar()
            cursor = conexion.cursor(dictionary=True)

            cursor.execute(
                """
                SELECT
                    COUNT(*) AS total,
                    ROUND(AVG(edad), 1) AS promedio_edad,
                    ROUND(AVG(anios_experiencia), 1) AS promedio_experiencia,
                    SUM(tipo_personal = 'Cuerpo docente') AS docentes,
                    SUM(tipo_personal = 'Cuerpo administrativo') AS administrativos,
                    SUM(tipo_personal = 'Cuerpo directivo') AS directivos,
                    SUM(
                        estudios_posgrado IS NOT NULL
                        AND TRIM(estudios_posgrado) <> ''
                    ) AS posgrado
                FROM maestros
                """
            )

            datos = cursor.fetchone()

            reporte = (
                "CESGRO - RESUMEN DEL PERSONAL ACADÉMICO\n"
                + "=" * 58
                + "\n\n"
                + f"Total de registros:           {datos['total'] or 0}\n"
                + f"Cuerpo docente:               {datos['docentes'] or 0}\n"
                + f"Cuerpo administrativo:        {datos['administrativos'] or 0}\n"
                + f"Cuerpo directivo:             {datos['directivos'] or 0}\n"
                + f"Personal con posgrado:        {datos['posgrado'] or 0}\n"
                + f"Promedio de edad:             {datos['promedio_edad'] or 0} años\n"
                + f"Promedio de experiencia:      {datos['promedio_experiencia'] or 0} años\n"
                + "\n"
                + f"Fecha del reporte: {datetime.now().strftime('%d/%m/%Y %H:%M')}"
            )

            self.texto_reporte.delete("1.0", "end")
            self.texto_reporte.insert("1.0", reporte)
            self.texto_reporte.config(state="disabled")

        except Error as error:
            messagebox.showerror(
                "Error",
                f"No se pudo generar el reporte.\n\n{error}"
            )

        finally:
            if cursor:
                cursor.close()

            if conexion and conexion.is_connected():
                conexion.close()

    def exportar_excel(self):
        ruta = filedialog.asksaveasfilename(
            title="Guardar reporte CESGRO",
            defaultextension=".xlsx",
            filetypes=[("Archivo de Excel", "*.xlsx")],
            initialfile=(
                "reporte_docentes_cesgro_"
                f"{datetime.now().strftime('%Y%m%d')}.xlsx"
            )
        )

        if not ruta:
            return

        conexion = None
        cursor = None

        try:
            conexion = conectar()
            cursor = conexion.cursor()

            cursor.execute(
                """
                SELECT
                    folio,
                    nombre,
                    apellidos,
                    edad,
                    sexo,
                    nacionalidad,
                    curp,
                    carrera,
                    cedula_profesional,
                    estudios_posgrado,
                    cedula_posgrado,
                    nivel_academico,
                    programa_academico,
                    modalidad,
                    anios_experiencia,
                    cargo,
                    tipo_personal,
                    DATE_FORMAT(fecha_registro, '%d/%m/%Y')
                FROM maestros
                ORDER BY tipo_personal, apellidos, nombre
                """
            )

            registros = cursor.fetchall()

            libro = Workbook()
            hoja = libro.active
            hoja.title = "Registro CESGRO"

            encabezados = [
                "Folio",
                "Nombre",
                "Apellido(s)",
                "Edad",
                "Sexo",
                "Nacionalidad",
                "CURP",
                "Nombre de la carrera",
                "Cédula profesional",
                "Estudios de posgrado",
                "Cédula de posgrado",
                "Nivel académico",
                "Programa académico",
                "Modalidad",
                "Años de experiencia",
                "Cargo",
                "Tipo de personal",
                "Fecha de registro"
            ]

            hoja.merge_cells(
                start_row=1,
                start_column=1,
                end_row=1,
                end_column=len(encabezados)
            )

            titulo = hoja.cell(1, 1)
            titulo.value = "CESGRO - Registro de maestros"
            titulo.font = Font(bold=True, size=16, color="FFFFFF")
            titulo.fill = PatternFill("solid", fgColor="0E6FA8")
            titulo.alignment = Alignment(
                horizontal="center",
                vertical="center"
            )
            hoja.row_dimensions[1].height = 30

            for columna, encabezado in enumerate(encabezados, start=1):
                celda = hoja.cell(3, columna, encabezado)
                celda.font = Font(bold=True, color="FFFFFF")
                celda.fill = PatternFill("solid", fgColor="084D78")
                celda.alignment = Alignment(
                    horizontal="center",
                    vertical="center",
                    wrap_text=True
                )

            for fila, registro in enumerate(registros, start=4):
                for columna, valor in enumerate(registro, start=1):
                    celda = hoja.cell(fila, columna, valor)
                    celda.alignment = Alignment(
                        vertical="center",
                        wrap_text=True
                    )

                    if fila % 2 == 0:
                        celda.fill = PatternFill(
                            "solid",
                            fgColor="F1F7FB"
                        )

            anchos = [18, 24, 8, 15, 17, 22, 30, 20, 32, 20, 16, 30, 16, 18, 22, 26, 18]

            for indice, ancho in enumerate(anchos, start=1):
                hoja.column_dimensions[get_column_letter(indice)].width = ancho

            hoja.freeze_panes = "A4"
            libro.save(ruta)

            messagebox.showinfo(
                "Exportación terminada",
                f"El archivo se guardó correctamente en:\n\n{ruta}"
            )

        except Exception as error:
            messagebox.showerror(
                "Error",
                f"No se pudo exportar el archivo.\n\n{error}"
            )

        finally:
            if cursor:
                cursor.close()

            if conexion and conexion.is_connected():
                conexion.close()


    def crear_respaldo_sql(self):
        """Genera un respaldo completo de MySQL en un archivo .sql."""
        ruta = filedialog.asksaveasfilename(
            title="Guardar respaldo de CESGRO",
            defaultextension=".sql",
            filetypes=[("Respaldo SQL", "*.sql")],
            initialfile=(
                "respaldo_cesgro_"
                f"{datetime.now().strftime('%Y%m%d_%H%M')}.sql"
            )
        )
        if not ruta:
            return

        ejecutable = shutil.which("mysqldump")
        if not ejecutable:
            posibles = [
                r"C:\Program Files\MySQL\MySQL Server 8.0\bin\mysqldump.exe",
                r"C:\Program Files\MySQL\MySQL Server 8.4\bin\mysqldump.exe",
                r"C:\xampp\mysql\bin\mysqldump.exe"
            ]
            ejecutable = next((x for x in posibles if os.path.exists(x)), None)

        if not ejecutable:
            messagebox.showerror(
                "No se encontró mysqldump",
                "No se encontró la herramienta de respaldo de MySQL. "
                "Verifica que MySQL Server esté instalado."
            )
            return

        try:
            comando = [
                ejecutable,
                f"--host={DB_HOST}",
                f"--port={DB_PORT}",
                f"--user={DB_USER}",
                f"--password={DB_PASSWORD}",
                "--single-transaction",
                DB_NAME
            ]
            with open(ruta, "w", encoding="utf-8") as archivo:
                proceso = subprocess.run(
                    comando,
                    stdout=archivo,
                    stderr=subprocess.PIPE,
                    text=True,
                    check=False,
                    creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0)
                )
            if proceso.returncode != 0:
                raise RuntimeError(proceso.stderr.strip() or "Error desconocido")

            messagebox.showinfo(
                "Respaldo creado",
                f"El respaldo se guardó correctamente en:\n\n{ruta}"
            )
            self.actualizar_estado("Respaldo SQL creado", COLORES["verde"])
        except (OSError, RuntimeError) as error:
            messagebox.showerror(
                "Error de respaldo",
                f"No se pudo crear el respaldo.\n\n{error}"
            )


